@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_item_stack_request_is_packet_147(version):
    assert version.PACKETS[147] is version.ItemStackRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_item_stack_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_item_stack_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_item_stack_request_2225_writes_craft_non_implemented_with_a_different_variant_and_type_than_2168():
    assert bytes(NON_IMPLEMENTED_V2225)[3:5] != NON_IMPLEMENTED_V2168[3:5]


def test_item_stack_request_2225_craft_non_implemented_round_trips():
    assert v2225.ItemStackRequestPacket.from_bytes(bytes(NON_IMPLEMENTED_V2225)) == NON_IMPLEMENTED_V2225


def test_item_stack_request_2225_leaves_the_rest_of_craft_non_implemented_unchanged():
    new = bytes(NON_IMPLEMENTED_V2225)
    assert new[:3] + new[5:] == NON_IMPLEMENTED_V2168[:3] + NON_IMPLEMENTED_V2168[5:]


def test_item_stack_request_2225_disc_press_is_sixteen_bytes():
    assert len(bytes(DISC_PRESS_V2225)) == 16


def test_item_stack_request_2225_disc_press_round_trips():
    assert v2225.ItemStackRequestPacket.from_bytes(bytes(DISC_PRESS_V2225)) == DISC_PRESS_V2225


def test_item_stack_request_2168_rejects_a_1001_body():
    with pytest.raises(ValueError, match="at byte"):
        v2168.ItemStackRequestPacket.from_bytes(TAKE_V1001)


def test_item_stack_request_1001_rejects_a_2168_body_it_desynchronises_on():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.ItemStackRequestPacket.from_bytes(TAKE_V2168)
